    package static func upper(_ text: String) -> String {
        var result = String()
        for scalar in text.unicodeScalars { result += uppercase[scalar.value] ?? String(scalar) }
        return result
    }
    private static let digitRanges: [(UInt16, UInt16)] = [
        (0x0030, 0x0039),
        (0x0660, 0x0669),
